  subsets: ["latin"],
  display: "swap",
  variable: "--font-dm-sans",
  weight: ["400", "500"], // Regular, Medium
});

const openSans = Open_Sans({
  subsets: ["latin"],
  display: "swap",
  variable: "--font-open-sans",
  weight: ["300", "400"], // Light (body), Regular
});

const lora = Lora({
  subsets: ["latin"],
  display: "swap",
  variable: "--font-lora",
  weight: ["400"], // Regular only (used with italic for editorial)
  style: ["normal", "italic"],
});

export const metadata: Metadata = {
  metadataBase: new URL('https://josephibrahim.com'),
  title: "Joseph Ibrahim — Problems of Light",
  description: "Lighting Technical Director with 16 years at MPC, Framestore, The Mill, and Method Studios delivering photorealistic CG lighting for feature films and commercials.",
  keywords: ["VFX", "Visual Effects", "Lighting TD", "Houdini", "Solaris", "USD", "Unreal Engine", "Real-time", "Feature Film"],
  authors: [{ name: "Joseph Ibrahim" }],
  creator: "Joseph Ibrahim",
  icons: {
    icon: [
      { url: '/icon.svg', type: 'image/svg+xml' },
    ],
  },
  openGraph: {
    type: "website",
    locale: "en_US",
    url: "https://josephibrahim.com",
    title: "Joseph Ibrahim — Problems of Light",
    description: "Sixteen years of lighting for feature films, commercials, and real-time engines. From Disney's Cinderella to Apple campaigns—each frame a problem of light solved in pixels.",
    siteName: "Joseph Ibrahim",
    images: [
      {
        url: "https://josephibrahim.com/og-image.png",
        width: 1200,
        height: 630,
        alt: "Joseph Ibrahim — Problems of Light",
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: "Joseph Ibrahim — Problems of Light",
    description: "Sixteen years of lighting for feature films, commercials, and real-time engines. From Disney's Cinderella to Apple campaigns—each frame a problem of light solved in pixels.",
    creator: "@josephibrahim",
    images: ["https://josephibrahim.com/og-image.png"],
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" style={{ colorScheme: 'dark', backgroundColor: '#141414' }} className={`${inter.variable} ${openSans.variable} ${lora.variable} ${dmSans.variable}`}>
      <head>
        <meta name="theme-color" content="#141414" />
        {/* color-scheme meta tag tells the browser to use dark canvas between navigations,
            preventing white flash on reload. Must be a meta tag (not just CSS) to take
            effect before first paint. */}
        <meta name="color-scheme" content="dark" />
